-- أدلة أكواد التأخير (فلاي دبي FZ + طيران النيل NP): يقرأها الموظف المسجّل فقط
-- شغّل هذا الملف مرة واحدة في Supabase: SQL Editor ← New query ← الصق ← Run
-- لإضافة دليل شركة جديدة لاحقاً: سطر insert جديد بنفس الطريقة

create table if not exists public.ajf_dcg (
  k   text primary key,
  v   jsonb not null,
  at  timestamptz not null default now()
);
alter table public.ajf_dcg enable row level security;
revoke all on public.ajf_dcg from public, anon, authenticated;

create or replace function public.ajf_dcg_get(p_token text, p_device text, p_k text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare me jsonb;
begin
  me := to_jsonb(public.ajf_me(p_token => p_token, p_device => p_device));
  if me is null or coalesce(me->>'emp','') = '' or me->>'s' = 'out' then return jsonb_build_object('s','out'); end if;
  return jsonb_build_object('s','ok','v',(select v from public.ajf_dcg where k = p_k));
end $$;
revoke all on function public.ajf_dcg_get(text,text,text) from public;
grant execute on function public.ajf_dcg_get(text,text,text) to anon, authenticated;

insert into public.ajf_dcg(k,v) values ('fz', $dcg${"airline":"FZ","name":"فلاي دبي · flydubai Delay Codes","short":"فلاي دبي","source":"FZ Delay Codes DEC 2023","tag":"مجموعة مناولة","note":"الكود رئيسي لحاله (مثل 32) أو مع حرف فرعي (مثل 32M). معنى الحرف الفرعي: B عطل · C الطاقم · D تأخر بدء أو إنهاء · E خطأ موظف · F نقص مرافق (مواقف، بوابات، كاونترات) · G ضرر · I أنظمة IT · L طلب متأخر · M نقص موظفين · P الركاب · S نقص معدات أرضية · W الطقس · X حجم زائد · U أخرى. «SI» تعني لازم تكتب معلومة إضافية مع الكود.","secs":{"1":{"en":"OTHERS","ar":"أخرى"},"2":{"en":"PASSENGER AND BAGGAGE","ar":"الركاب والعفش"},"3":{"en":"CARGO AND MAIL","ar":"الشحن والبريد"},"4":{"en":"AIRCRAFT AND RAMP HANDLING","ar":"مناولة الطائرة والساحة"},"5":{"en":"TECHNICAL AND AIRCRAFT EQUIPMENT","ar":"الفني ومعدات الطائرة"},"6":{"en":"DAMAGE TO AIRCRAFT","ar":"ضرر للطائرة"},"7":{"en":"EDP / AUTOMATED EQUIPMENT FAILURE","ar":"أعطال الأنظمة"},"8":{"en":"FLIGHT OPERATIONS AND CREWING","ar":"العمليات الجوية والطاقم"},"9":{"en":"WEATHER","ar":"الطقس"},"10":{"en":"AIR TRAFFIC FLOW MANAGEMENT RESTRICTIONS","ar":"قيود إدارة الحركة الجوية ATFM"},"11":{"en":"AIRPORT AND GOVERNMENTAL AUTHORITIES","ar":"المطار والجهات الحكومية"},"12":{"en":"REACTIONARY","ar":"التبعي (Reactionary)"},"13":{"en":"MISCELLANEOUS","ar":"متفرقة"}},"codes":[{"c":"11","a":"","en":"Late check-in, acceptance after deadline","ar":"إجراءات متأخرة، قبول راكب بعد إغلاق الكاونتر","sec":2,"subs":[["","Late check-in, acceptance after deadline","",1],["E","Late check-in - acceptance after deadline - late closure of check in due staff error","",1],["I","Late check-in - acceptance after deadline - late closure of check in due system issues, IT","",1],["M","Late check-in - acceptance after deadline - late closure of check in due manpower shortage","",1]],"sa":{"":"إجراءات متأخرة، قبول راكب بعد إغلاق الكاونتر","E":"قبول بعد الإغلاق: تأخر إغلاق الكاونتر بسبب خطأ موظف","I":"قبول بعد الإغلاق: تأخر إغلاق الكاونتر بسبب عطل نظام/تقنية","M":"قبول بعد الإغلاق: تأخر إغلاق الكاونتر بسبب نقص الموظفين"}},{"c":"12","a":"","en":"Late check-in, congestions in check-in area","ar":"إجراءات متأخرة بسبب زحمة منطقة الكاونترات","sec":2,"subs":[["","Late check-in, congestions in check-in area","",1],["B","Late check in - congestion in check-in area due pax volume - belt failure OR power or desk equipment","",1],["F","Late check-in, congestion in check-in area due pax volume AND lack of check in counters","",1],["X","Late check in - congestion in check-in area due pax volume - this is pax presentation and can be used for peak times when pax presentation is late, or late arrival of groups","",1]],"sa":{"":"إجراءات متأخرة بسبب زحمة منطقة الكاونترات","B":"زحمة الكاونترات: عطل السير أو الكهرباء أو أجهزة الكاونتر","F":"زحمة الكاونترات بسبب عدد الركاب ونقص الكاونترات","X":"زحمة الكاونترات بسبب عدد الركاب: حضور متأخر للركاب في الذروة أو وصول مجموعات متأخر"}},{"c":"13","a":"","en":"CHECK-IN ERROR, passenger and baggage","ar":"خطأ في إجراءات السفر (راكب وعفش)","sec":2,"subs":[["","CHECK-IN ERROR, passenger and baggage","",1],["E","CHECK-IN ERROR, passenger and baggage - staff error, mistake at check in","",1],["P","CHECK-IN ERROR, passenger and baggage - pax error, mistake at check in due pax providing wrong information","",1]],"sa":{"":"خطأ في إجراءات السفر (راكب وعفش)","E":"خطأ موظف في إجراءات السفر","P":"خطأ من الراكب في الإجراءات (أعطى معلومات غلط)"}},{"c":"14","a":"","en":"OVERSALES, booking errors","ar":"زيادة حجز (Oversales) أو أخطاء حجز","sec":2,"subs":[["","OVERSALES, booking errors","",1],["I","FZ internal IT failure/downtime/interface issue e.g Booking & Pricing Engine Error (Farelogix / Vayant / Sprint PSS)","",1],["X","Oversales of baggage SSR result in baggage loading delay and left behind","",1]],"sa":{"":"زيادة حجز (Oversales) أو أخطاء حجز","I":"عطل أنظمة فلاي دبي الداخلية (محرك الحجز والتسعير)","X":"زيادة حجز طلبات العفش الخاصة SSR أدّت لتأخر التحميل وترك عفش"}},{"c":"15","a":"","en":"BOARDING, discrepancies and paging, mis